# Rig map of card flags: circuits/flags/flags.circ circuit flags; vectors: hbc2 vectors flags
# Generated by tools/rigmap.py gen, then edited by hand if needed (notes/test-rig.md).
# Third column: the card connector pin, once the pinout is decided.
#
# rig         pins
C0            clk
D0            flags_op[0]
D1            flags_op[1]
D2            flags_op[2]
D3            flags_op[3]
D4            flags_bit_val
D5            flags_oe_n
D6            rst_n
D7            flags_alu_c
D8            flags_alu_z
D9            flags_alu_n
D10           flags_alu_s
D11           flags_alu_e
D12           flags_alu_f
S0            flag_c
S1            flag_e
S2            flag_i
S3            flag_n
S4            flag_s
S5            flag_z
S6            flag_f
S7            flag_h
D16+S8        flags_bus_in[0]+flags_bus_out[0]
D17+S9        flags_bus_in[1]+flags_bus_out[1]
D18+S10       flags_bus_in[2]+flags_bus_out[2]
D19+S11       flags_bus_in[3]+flags_bus_out[3]
D20+S12       flags_bus_in[4]+flags_bus_out[4]
D21+S13       flags_bus_in[5]+flags_bus_out[5]
D22+S14       flags_bus_in[6]+flags_bus_out[6]
D23+S15       flags_bus_in[7]+flags_bus_out[7]
